//! # ergo-aeron-cluster
//!
//! Experimental Rust client for [Aeron Cluster](https://github.com/real-logic/aeron).
//!
//! It builds on [`rusteron_client`] 0.2 and uses session codecs (schema 111)
//! generated by ergo-sbe.
//!
//! # Documentation
//!
//! - [The ergo-sbe book](https://mimran1980.github.io/ergon/): the cluster client guide
//! - [Overview](https://mimran1980.github.io/ergon/cluster/overview.html),
//!   [SessionBuilder](https://mimran1980.github.io/ergon/cluster/session-builder.html),
//!   [Egress listeners](https://mimran1980.github.io/ergon/cluster/egress-listeners.html) and
//!   [Chained decoding](https://mimran1980.github.io/ergon/cluster/chained-decoding.html)
//! - [Crate README](https://github.com/mimran1980/ergon/blob/main/cluster/README.md)
//!
//! This is a prototype, written with LLM assistance and less tested than the
//! Java reference. A bug in rusteron or in this crate can cause undefined
//! behaviour, a segfault or data loss. Switch to the official Cluster C client
//! bindings once they suit your deployment.
//!
//! # Client only
//!
//! The crate implements the client side of the Aeron Cluster protocol, in
//! parity with Java
//! [`io.aeron.cluster.client`](https://github.com/real-logic/aeron/tree/master/aeron-cluster/src/main/java/io/aeron/cluster/client):
//! connect, offer and `try_claim`, egress polling, leader failover, keep-alive,
//! admin snapshot and challenge-response authentication. It does not implement
//! the cluster server and never will: no consensus module (Raft), clustered
//! service container, leader election, snapshots or recovery, archive, backup
//! node or `ClusterTool` CLI. The Java Aeron process runs all of those, and
//! this client talks to it over the standard Aeron wire protocol.
//!
//! # Hot path
//!
//! 1. [`AeronCluster::try_claim`] writes the `SessionMessageHeader` into the claim.
//! 2. [`AeronCluster::poll`] decodes egress (`SessionEvent`, `NewLeader`, application messages)
//!    and tracks session state.
//! 3. Keep-alive encoding runs periodically.
//!
//! Connect, authentication and failover are cold paths that favour correctness
//! over nanoseconds.
//!
//! # Codecs
//!
//! `codecs::session` (schema 111) and `codecs::mark` are generated in
//! `build.rs` from the vendored Aeron schemas. The sbe-tool reference runtime
//! in `cluster/benches/reference_sbe/` is private to Criterion and is never
//! imported from library, test or example code.
//!
//! # Quick connect
//!
//! ```rust
//! use std::sync::Arc;
//! use ergo_aeron_cluster::{
//!     SessionBuilder,
//!     NullCredentialsSupplier,
//!     StaticCredentials,
//! };
//! fn demo() -> Result<(), ergo_aeron_cluster::ClusterError> {
//!     let builder = SessionBuilder::default()
//!         .ingress_channel("aeron:udp?endpoint=localhost:9010")?
//!         .egress_channel("aeron:udp?endpoint=localhost:9020")?
//!         .credentials(Arc::new(StaticCredentials::from_utf8("user:pass")))
//!         .message_timeout(std::time::Duration::from_secs(5))?;
//!     builder.validate()
//! }
//! demo().expect("valid config");
//! ```
//!
//! ```rust,no_run
//! use ergo_aeron_cluster::{AeronCluster, ClusterError, SessionBuilder};
//!
//! fn publish(aeron_dir: &str, app_bytes: &[u8]) -> Result<(), ClusterError> {
//!     let builder = SessionBuilder::default()
//!         .ingress_channel("aeron:udp?endpoint=localhost:9010")?
//!         .egress_channel("aeron:udp?endpoint=localhost:9020")?;
//!     let mut client = AeronCluster::connect(&builder, aeron_dir)?;
//!     let mut claim = client.try_claim(app_bytes.len())?;
//!     claim.payload_mut().copy_from_slice(app_bytes);
//!     claim.commit()?;
//!     Ok(())
//! }
//! ```
//!
//! The [book](https://mimran1980.github.io/ergon/cluster/overview.html) and
//! [crate README](https://github.com/mimran1980/ergon/blob/main/cluster/README.md)
//! have recipes, the maintained benches and the HA sample.

#[doc(hidden)]
pub mod transport {
    pub use rusteron_client::Aeron;
    pub use rusteron_client::AeronContext;
    pub use rusteron_client::AeronExclusivePublication;
    pub use rusteron_client::AeronPublication;
    pub use rusteron_client::AeronSubscription;
}

pub mod client;
/// SBE codecs: the ergo-sbe production modules and the sbe-tool trees the benches compare against.
pub(crate) mod codecs;

/// Generated codec types re-exported for integration tests and benches only.
/// They are not a stable API: use `AeronCluster` instead.
#[doc(hidden)]
pub mod cluster_codec_types {
    pub use crate::codecs::session::{
        AdminRequestEncoder, AdminRequestFixedFields, AdminRequestType, AdminResponseCode, AdminResponseEncoder,
        AdminResponseFixedFields, AnyMessage, ChallengeDecoder, ChallengeEncoder, ChallengeFixedFields,
        ChallengeResponseEncoder, ChallengeResponseFixedFields, EventCode, NewLeaderEventDecoder,
        NewLeaderEventEncoder, NewLeaderEventFixedFields, SessionCloseRequestEncoder, SessionCloseRequestFixedFields,
        SessionConnectRequestEncoder, SessionConnectRequestFixedFields, SessionEventDecoder, SessionEventEncoder,
        SessionEventFixedFields, SessionKeepAliveEncoder, SessionKeepAliveFixedFields, SessionMessageHeaderDecoder,
        SessionMessageHeaderEncoder, SessionMessageHeaderFixedFields,
    };
}
/// [`SessionBuilder`] configuration for connect.
pub mod config;
/// Credential supplier traits for challenge-response auth.
pub mod credentials;
/// Session-message header applied to a raw publication.
pub mod decorator;
/// The egress listener [`AeronCluster::poll`] calls.
pub mod egress;
/// Multi-member ingress endpoint maps (`0=host:port,…`).
pub mod endpoints;
/// Cluster client error type.
pub mod error;
/// One decode of an egress fragment. Not public API.
pub(crate) mod fragment;
/// Poll-loop idle helpers ([`rusteron_client::IdleStrategy`]).
pub mod idle;
/// Parses the egress events seen during connect (`SessionEvent`, `NewLeader`, redirects).
mod poller;
/// Connect-protocol constants shared by the blocking and polled handshakes.
mod protocol;
/// [`SessionState`] machine for connected / new-leader / closed.
pub mod state;
/// Aeron channel URI helpers (`AeronUriStringBuilder`).
mod uri;

pub use client::{AeronCluster, AsyncClusterConnect, ClusterClaim, ConnectStep};
pub use config::SessionBuilder;
pub use credentials::{CredentialsSupplier, NullCredentialsSupplier, StaticCredentials};
pub use decorator::IngressSessionDecorator;
pub use egress::{EgressListener, NullListener};
pub use endpoints::{IngressEndpoint, parse_ingress_endpoints};
pub use error::{AeronErrorSource, ClusterError, ClusterEvent, PublicationFailure};
pub use idle::{default_idle, poll_connect_until_done};
pub use state::SessionState;
pub use uri::AERON_IPC_STREAM;

